export function ayahOfTheDay(date = new Date()) {
  const start = new Date(date.getFullYear(), 0, 0);
  const day = Math.floor((date - start) / 86400000);
  return AYAT[(day * 7 + date.getFullYear()) % AYAT.length];
}
